struct Veyikil {
    var vitès = 0
    mutating func akselere() {
        vitès += 10
    }
}

protocol Kondwi {
    func demare()
}

var machin = Veyikil()
machin.akselere()
print(machin.vitès)

let doub = { (n: Int) -> Int in n * 2 }
