func chajeNon() async -> String {
    try? await Task.sleep(nanoseconds: 500_000_000)
    return "Garry"
}

Task {
    let non = await chajeNon()
    print("Bonjou, \(non)!")
}

actor Kont {
    var balans = 0
    func depoze(_ montan: Int) {
        balans += montan
    }
}

let kont = Kont()
Task {
    await kont.depoze(100)
    print(await kont.balans)
}

struct KontèView: View {
    @State private var kontè = 0
    var body: some View {
        VStack {
            Text("Kontè: \(kontè)")
            Button("Mete +1") { kontè += 1 }
        }
    }
}

class Sèvis {
    var konplesyon: (() -> Void)?
    func demare() {
        konplesyon = { [weak self] in
            self?.fini()
        }
    }
    func fini() { print("Fini") }
}
